(()=>{document.body.style.cssText='margin:0;font:14px Arial;line-height:1.5;color:rgb(2,3,4)';const out={};for(const mode of ['open','closed']){const host=document.createElement('div');document.body.append(host);const root=host.attachShadow({mode});const inner=document.createElement('section');root.append(inner);const nested=inner.attachShadow({mode:'closed'});const leaf=document.createElement('div');leaf.style.fontSize='2em';leaf.textContent='Alpha beta';nested.append(leaf);const sample=()=>{const c=getComputedStyle(leaf),r=leaf.getBoundingClientRect();return {font:c.fontSize,family:c.fontFamily,color:c.color,line:c.lineHeight,height:r.height}};out[mode+'Initial']=sample();host.style.cssText='font-size:18px;color:rgb(5,6,7)';out[mode+'Changed']=sample();inner.style.fontFamily='"Times New Roman"';out[mode+'Override']=sample();host.remove();out[mode+'Detached']=getComputedStyle(leaf).fontSize;document.body.append(host);out[mode+'Reconnect']=sample();host.remove()}return out})()